import{_ as t,o,c as a,a0 as i}from"./chunks/framework.ZNXClGez.js";const u=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/upgrading.md","filePath":"guide/deployment/upgrading.md"}'),s={name:"guide/deployment/upgrading.md"};function n(r,e,d,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>This page collects <strong>action-required</strong> notes for upgrading an existing deployment. Entries are grouped by release, newest first. Routine changes (features, fixes) live in the <a href="https://github.com/authup/authup/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>; anything listed here either requires operator action or deliberately changes behavior.</p><h2 id="next-release-after-v1-0-0-beta-62" tabindex="-1">Next release (after v1.0.0-beta.62) <a class="header-anchor" href="#next-release-after-v1-0-0-beta-62" aria-label="Permalink to &quot;Next release (after v1.0.0-beta.62)&quot;">​</a></h2><h3 id="docker-the-writable-directory-moved-to-var-lib-authup" tabindex="-1">Docker: the writable directory moved to <code>/var/lib/authup</code> <a class="header-anchor" href="#docker-the-writable-directory-moved-to-var-lib-authup" aria-label="Permalink to &quot;Docker: the writable directory moved to `/var/lib/authup`&quot;">​</a></h3><p>The image wrote its runtime files to <code>/usr/src/app/writable</code>, inside the application install directory. It now uses <code>/var/lib/authup</code>, which is where the filesystem hierarchy standard puts mutable application state and which is a cleaner mount point than a path nested in the install tree.</p><p><strong>Action required if you mount a volume at the old path.</strong> Update the mount target; the volume itself is unchanged.</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> volumes:</span></span>\n<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-  - authup:/usr/src/app/writable</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+  - authup:/var/lib/authup</span></span></code></pre></div><p>The same applies to a bind-mounted provisioning directory: <code>-v /path/to/provisioning:/var/lib/authup/provisioning</code>.</p><p>Miss this and nothing fails loudly: the container starts, writes its production log files inside the container layer instead of the volume, and finds no provisioning files, so file-based provisioning silently stops being applied. Set <code>WRITABLE_DIRECTORY_PATH=/usr/src/app/writable</code> to keep the old location instead.</p><p>Only the image default changed. Running outside Docker still defaults to <code>writable</code> relative to the application root, so an unprivileged <code>npx</code> or bare-metal start is unaffected.</p><h3 id="a-relative-writabledirectorypath-now-resolves-against-rootpath" tabindex="-1">A relative <code>writableDirectoryPath</code> now resolves against <code>rootPath</code> <a class="header-anchor" href="#a-relative-writabledirectorypath-now-resolves-against-rootpath" aria-label="Permalink to &quot;A relative `writableDirectoryPath` now resolves against `rootPath`&quot;">​</a></h3><p>The documented behavior - a relative path is resolved against <code>rootPath</code> - was implemented for <code>themeDirectoryPath</code>, <code>authConsolePath</code> and <code>accountConsolePath</code> but not for <code>writableDirectoryPath</code>, which stayed relative to the process working directory and ignored <code>rootPath</code> entirely. It now resolves like its siblings.</p><p>This only changes behavior for a deployment that sets <code>rootPath</code> to something other than the working directory <strong>and</strong> gives <code>writableDirectoryPath</code> a relative value. Absolute values, and the default, are unaffected.</p><h3 id="get-identity-providers-id-now-requires-authentication" tabindex="-1"><code>GET /identity-providers/:id</code> now requires authentication <a class="header-anchor" href="#get-identity-providers-id-now-requires-authentication" aria-label="Permalink to &quot;`GET /identity-providers/:id` now requires authentication&quot;">​</a></h3><p>The endpoint was anonymous. It now requires an identity holding one of <code>IDENTITY_PROVIDER_READ</code>, <code>IDENTITY_PROVIDER_UPDATE</code> or <code>IDENTITY_PROVIDER_DELETE</code> for that provider&#39;s realm. A request without a token answers <code>401</code>; an authenticated caller lacking the permission answers <code>403</code> with code <code>permission_evaluation_failed</code>.</p><p>The record read carries the provider&#39;s extra attributes, which for an OAuth2 provider include <code>clientSecret</code> and for an LDAP provider the bind password. The previous behavior handed those to anyone who knew a provider id.</p><p><strong>Action required only if you read a single provider without a token.</strong> The collection stays anonymous, because the hosted login page lists providers before anyone signs in, and it never carries the extra attributes. Read the one provider from it instead:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /identity-providers?filter[id]=&lt;provider-id&gt;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /identity-providers?filter[name]=&lt;provider-name&gt;</span></span></code></pre></div><p>Both key forms the record route accepted are filterable, so a caller addressing a provider by name has a substitute too.</p><h2 id="v1-0-0-beta-62" tabindex="-1">v1.0.0-beta.62 <a class="header-anchor" href="#v1-0-0-beta-62" aria-label="Permalink to &quot;v1.0.0-beta.62&quot;">​</a></h2><h3 id="auth-identity-provider-accounts-gains-a-unique-constraint" tabindex="-1"><code>auth_identity_provider_accounts</code> gains a unique constraint <a class="header-anchor" href="#auth-identity-provider-accounts-gains-a-unique-constraint" aria-label="Permalink to &quot;`auth_identity_provider_accounts` gains a unique constraint&quot;">​</a></h3><p><code>(provider_id, provider_user_id)</code> becomes unique, so one external identity belongs to exactly one local user. Until now that invariant was enforced only by a read-then-write in the application, with no transaction and no row lock, so two concurrent logins or link completions for the same upstream subject could both insert. After that the subject resolved to whichever row the database happened to order first.</p><p><strong>Action required only if your deployment already holds such duplicates.</strong> The migration checks first and aborts the boot with the number of affected groups rather than a hash-named driver error. Find them with:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> provider_id, provider_user_id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> auth_identity_provider_accounts</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GROUP BY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> provider_id, provider_user_id</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HAVING</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> COUNT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Keep the row whose <code>user_id</code> names the account the person actually uses, and delete the rest. The unique index cannot be created while duplicates exist, so the boot would fail either way; the check only makes the reason readable.</p><h3 id="federated-login-completion-hardening" tabindex="-1">Federated login: completion hardening <a class="header-anchor" href="#federated-login-completion-hardening" aria-label="Permalink to &quot;Federated login: completion hardening&quot;">​</a></h3><ul><li>A federated login must carry the authorization code request it completes. <code>GET /identity-providers/:id/authorize-out</code> refuses a request without <code>codeRequest</code> (<code>invalid_request</code>). SDK consumers building their own login page pass it through the client: <code>client.identityProvider.getAuthorizeUri(id, { codeRequest })</code>; the bare <code>getAuthorizeUri(id)</code> URL no longer starts a login on its own.</li><li>The callback completes the request by redirecting the browser to the client&#39;s own <code>redirect_uri</code> with <code>code</code> and <code>state</code> (RFC 6749). A refusal after the callback lands on the hosted login page instead of a JSON body, and a provider answering with <code>error</code> (the user cancelled) does the same.</li><li>A custom-scheme <code>redirect_uri</code> (<code>myapp://cb</code>, RFC 8252) is served through an interstitial page that launches the app. Script-capable and local schemes (<code>javascript:</code>, <code>data:</code>, <code>vbscript:</code>, <code>blob:</code>, <code>filesystem:</code>, <code>file:</code>, <code>about:</code>) are refused everywhere: as a client redirect pattern, at <code>/authorize</code>, and at the callback.</li><li>A <code>redirectUri</code> / <code>postLogoutRedirectUri</code> pattern carrying userinfo (<code>https://user:pass@app/**</code>) is refused by the client validator, as is a <code>redirect_uri</code> carrying one at <code>/authorize</code> and <code>/logout</code>. An existing client row holding such a pattern cannot be saved again until the pattern is fixed, and a provisioning file declaring one fails the boot with the file path and the issue.</li><li>The pending-login state a federated login or an account link carries moved to its own cache namespace, so a login or link started on the previous version and completed after the upgrade is refused (<code>invalid_request</code>, up to the 30 minute state lifetime); the person starts it again. Relevant for a rolling upgrade over a shared Redis only.</li><li>The identity-provider form&#39;s read-only &quot;Redirect URL&quot; now shows the callback (<code>/identity-providers/&lt;id&gt;/authorize-in</code>), the value to register at the external provider. It used to show <code>authorize-out</code>, which is the URL that starts a login, not the one the provider redirects back to.</li><li>A substituted auth console package (<code>AUTH_CONSOLE_PATH</code>) must be built against render contract version 2, which adds the interstitial route <code>/identity-providers/:id/authorize-in</code> and its <code>IdentityProviderCallbackPayload</code>; a package exporting an older <code>CONTRACT_VERSION</code> is refused at boot.</li></ul><h2 id="v1-0-0-beta-60" tabindex="-1">v1.0.0-beta.60 <a class="header-anchor" href="#v1-0-0-beta-60" aria-label="Permalink to &quot;v1.0.0-beta.60&quot;">​</a></h2><h3 id="fixed-external-identity-provider-login" tabindex="-1">Fixed: external identity-provider login <a class="header-anchor" href="#fixed-external-identity-provider-login" aria-label="Permalink to &quot;Fixed: external identity-provider login&quot;">​</a></h3><p>The token exchange against an external OAuth2 / OIDC provider never sent the <code>code</code> parameter, so <strong>every federated login has failed since v1.0.0-beta.28</strong> with an <code>invalid_request</code> from the provider&#39;s token endpoint. The callback passed the raw code string where the authenticator expected <code>{ code }</code>, and the HTTP client spread it into indexed body keys (<code>0=d&amp;1=b&amp;...</code>). <strong>No action is required</strong> beyond upgrading. A callback that arrives without a code is now rejected with a <code>400</code> instead of an opaque upstream failure.</p><h3 id="auth-sessions-client-id-is-the-client-subject-foreign-key-only" tabindex="-1"><code>auth_sessions.client_id</code> is the client-subject foreign key only <a class="header-anchor" href="#auth-sessions-client-id-is-the-client-subject-foreign-key-only" aria-label="Permalink to &quot;`auth_sessions.client_id` is the client-subject foreign key only&quot;">​</a></h3><p>One browser session legitimately serves several applications (the hosted auth pages and the account console share the IdP origin by design), so a single column could never name all of them: it was last-writer-wins and accurate for none. Per-application attribution moved one level down, onto <code>auth_session_tokens.client_id</code>.</p><p><code>auth_sessions.client_id</code> now means what its foreign key always implied — the subject of a <strong>client</strong> session — and is <code>NULL</code> for a user&#39;s session. Nothing writes the authorizing application there anymore.</p><ul><li><strong>Runbooks that sign an identity out of one application must change</strong>: <code>DELETE /sessions?filter[clientId]=...</code> no longer matches user sessions. Use <code>DELETE /session-tokens?filter[clientId]=...</code>, which revokes that application&#39;s tokens and leaves the session alive so the others stay signed in. To sign an identity out everywhere, filter by <code>userId</code> instead.</li><li><strong>Sessions created before the upgrade keep the old value.</strong> No backfill ships, because the column is behind <code>ON DELETE CASCADE</code>: until those rows expire (session lifetime, three days by default), deleting a retired client still force-logs-out the users whose sessions recorded it. Either wait out the lifetime before deleting a client, or run <code>UPDATE auth_sessions SET client_id = NULL WHERE sub_kind &lt;&gt; &#39;client&#39;</code>.</li></ul><h3 id="schema-migration-constraint-names-mysql-column-widths-140-indexes" tabindex="-1">Schema migration: constraint names, MySQL column widths, 140 indexes <a class="header-anchor" href="#schema-migration-constraint-names-mysql-column-widths-140-indexes" aria-label="Permalink to &quot;Schema migration: constraint names, MySQL column widths, 140 indexes&quot;">​</a></h3><p>Two migrations apply. Both are safe to run on a populated database, and the round trip is verified in CI against MySQL and PostgreSQL, but the second one is not instant on a large instance. <strong>Run <code>authup migration run</code> before the rolling restart</strong> rather than letting the first pod apply it under traffic.</p><ul><li>Index, unique and foreign-key names move onto the values TypeORM derives from the entity metadata. Names have no runtime meaning; this only ends a split where two naming regimes coexisted and every generated migration emitted 32 renames before its actual change.</li><li><strong>MySQL only</strong>: 15 <code>uuid</code> columns widen from <code>varchar(36)</code> to the <code>varchar(255)</code> TypeORM derives for them. This rewrites those tables, blocks writes for the duration and needs disk headroom for the copy. It runs first and is re-runnable, so an interrupted upgrade retries cleanly.</li><li>140 indexes are added, backing the filter and sort vocabulary each entity advertises (see below) and the remaining foreign-key columns. On PostgreSQL the migrations run in one transaction, so the largest tables (<code>auth_events</code>, <code>auth_sessions</code>, <code>auth_session_tokens</code>) are locked for the duration of the build.</li><li>Three orphaned tables are <strong>dropped with their rows</strong>: <code>auth_authorization_codes</code>, <code>auth_refresh_tokens</code> and <code>auth_identity_provider_roles</code>. Each was superseded years ago (codes moved to cache blobs, refresh tokens to <code>auth_session_tokens</code>, provider roles to <code>auth_identity_provider_role_mappings</code>) and no entity has described them since. Back them up first if you still read them out of band.</li></ul><h3 id="api-meta-schema-sort-is-now-meta-schema-sorts" tabindex="-1">API: <code>meta.schema.sort</code> is now <code>meta.schema.sorts</code> <a class="header-anchor" href="#api-meta-schema-sort-is-now-meta-schema-sorts" aria-label="Permalink to &quot;API: `meta.schema.sort` is now `meta.schema.sorts`&quot;">​</a></h3><p>The query-capable <code>GET</code> endpoints describe their vocabulary under <code>meta.schema</code>. Its sort key was renamed <code>sort</code> → <code>sorts</code> (rapiq 2.1.0, which made <code>sorts</code> canonical on every developer-authored surface). <strong>A client that reads <code>meta.schema.sort</code> must follow</strong>; there is no alias. The <code>?sort=-name</code> URL parameter is unchanged.</p><p>Filters and sorts are also index-anchored now: every key an endpoint allows is backed by a real index, so single-key filters and sorts behave exactly as before. The one narrowing is a <strong>multi-key sort</strong> with no matching composite index prefix, which is now dropped whole rather than executed — the request still succeeds, unsorted.</p><h2 id="v1-0-0-beta-59" tabindex="-1">v1.0.0-beta.59 <a class="header-anchor" href="#v1-0-0-beta-59" aria-label="Permalink to &quot;v1.0.0-beta.59&quot;">​</a></h2><h3 id="security-fix-redirect-patterns-with-a-host-wildcard" tabindex="-1">Security fix: redirect patterns with a host wildcard <a class="header-anchor" href="#security-fix-redirect-patterns-with-a-host-wildcard" aria-label="Permalink to &quot;Security fix: redirect patterns with a host wildcard&quot;">​</a></h3><p>A <code>redirectUri</code> / <code>postLogoutRedirectUri</code> pattern carrying a <code>*</code> in its host (<code>https://*.example.com/**</code>) matched more than its host. The matcher treats <code>/</code> as its only boundary, while a URL authority also ends at <code>?</code>, <code>#</code> and <code>\\</code>, so <code>https://evil.test?.example.com/cb</code> matched the pattern above and an authorization code was issued to <code>evil.test</code>.</p><p>The candidate is now canonicalized before matching, so the string that gets authorized is the string the browser navigates to. <strong>No action is required</strong>, and no legitimate redirect stops matching. Three side effects are worth knowing:</p><ol><li>Both the request and the stored pattern are normalized before comparison, so a host differing only in case, an explicit default port (<code>:443</code> on https) and <code>.</code>/<code>..</code> segments resolve on either side. A path-scoped pattern can no longer be walked out of with <code>..</code>, and a pattern that was written non-canonically (<code>https://APP.example.com/**</code>, <code>https://app.example.com:443/**</code>) now matches the requests it always looked like it should.</li><li><code>**</code> is no longer accepted inside the host of a pattern. It matches the rest of the value outright, so <code>https://**.example.com/**</code> read as &quot;any subdomain&quot; but accepted every origin. A single <code>*</code> is unchanged: it matches any run of characters that does not cross a <code>/</code>, so it spans dots and <code>https://*.example.com/**</code> covers <code>https://a.b.example.com/cb</code> as well as <code>https://a.example.com/cb</code>. A stored pattern is not rewritten; only new writes are rejected.</li><li><code>TRUSTED_ORIGINS</code> rejects the same shape at startup, with a message naming the offending value.</li></ol><h3 id="client-web-was-renamed-to-client-admin-console" tabindex="-1"><code>client/web</code> was renamed to <code>client/admin-console</code> <a class="header-anchor" href="#client-web-was-renamed-to-client-admin-console" aria-label="Permalink to &quot;`client/web` was renamed to `client/admin-console`&quot;">​</a></h3><p>The rename of the admin console app (<code>@authup/client-web</code> → <code>@authup/client-admin-console</code>) reaches the operator surface. There is <strong>no backwards alias</strong>, and an unknown selector is now a hard error instead of a silent success:</p><ul><li><strong>Docker</strong>: <code>docker run authup/authup client/web start</code> → <code>client/admin-console start</code>. The entrypoint used to exit <code>0</code> on an unknown service, so this previously looked like a healthy container that started nothing. It now exits <code>1</code>.</li><li><strong>Launcher config</strong>: a <code>client.web</code> section in <code>authup.conf</code> is no longer read. Rename it to <code>client.admin-console</code>, otherwise every key in it (<code>port</code>, <code>host</code>, <code>apiUrl</code>, <code>cookieDomain</code>) silently falls back to its default.</li><li><strong>CLI</strong>: <code>authup start client/web</code> → <code>authup start client/admin-console</code>.</li><li><strong>Binary</strong>: <code>authup-ui</code> → <code>authup-admin-console</code>.</li></ul><h3 id="admin-console-and-account-console-are-reserved-client-names" tabindex="-1"><code>admin-console</code> and <code>account-console</code> are reserved client names <a class="header-anchor" href="#admin-console-and-account-console-are-reserved-client-names" aria-label="Permalink to &quot;`admin-console` and `account-console` are reserved client names&quot;">​</a></h3><p>Both names are now provisioned as system clients in every realm. If a client of either name already exists, <strong>it is taken over</strong> rather than left alone: the provisioner overwrites <code>name</code>, <code>realmId</code>, <code>authMethod</code>, <code>tokenBindingMethod</code>, <code>builtIn</code>, <code>active</code>, <code>grantTypes</code>, <code>scope</code>, <code>redirectUri</code> and <code>postLogoutRedirectUri</code>, which makes it a public (secret-less) auto-consenting client.</p><p>Rename any existing client on those names <strong>before</strong> upgrading. Attributes outside that list (<code>displayName</code>, <code>description</code>, <code>accessPolicyId</code>, junction rows) are preserved.</p><h3 id="the-per-realm-web-client-was-removed" tabindex="-1">The per-realm <code>web</code> client was removed <a class="header-anchor" href="#the-per-realm-web-client-was-removed" aria-label="Permalink to &quot;The per-realm `web` client was removed&quot;">​</a></h3><p>The shared <code>web</code> system client is no longer provisioned. Authup&#39;s own consoles were moved off it earlier (<code>admin-console</code> / <code>account-console</code>); it existed purely for downstream applications and was default-on attack surface (auto-consent + <code>global</code> scope in every realm).</p><p><strong>Existing <code>web</code> rows are not touched</strong>: logins against them keep working. Two behavior changes require action:</p><ol><li><code>PUBLIC_URL</code> / <code>TRUSTED_ORIGINS</code> changes no longer propagate to the leftover rows; their <code>redirectUri</code> / <code>postLogoutRedirectUri</code> are frozen as-is.</li><li>Realms created after the upgrade get no <code>web</code> client, so a <code>client_id=web</code> login breaks there.</li></ol><p>Register a client of your own instead. To keep the every-realm semantics, declare it once via a <a href="./provisioning.html#realm-wildcard-name">wildcard realm entry</a> (<code>realms[].attributes.name: &quot;*&quot;</code>), which also offers a declarative <code>absent</code> cleanup for the leftover <code>web</code> rows. <code>CLIENT_WEB_NAME</code> was removed from <code>@authup/core-kit</code>, and <code>web</code> is a regular, creatable client name again.</p><h2 id="v1-0-0-beta-52-was-next-release-after-v1-0-0-beta-51" tabindex="-1">v1.0.0-beta.52 (was: next release after v1.0.0-beta.51) <a class="header-anchor" href="#v1-0-0-beta-52-was-next-release-after-v1-0-0-beta-51" aria-label="Permalink to &quot;v1.0.0-beta.52 (was: next release after v1.0.0-beta.51)&quot;">​</a></h2><h3 id="login-redirect-allowlist-—-set-trusted-origins" tabindex="-1">Login redirect allowlist — set <code>TRUSTED_ORIGINS</code> <a class="header-anchor" href="#login-redirect-allowlist-—-set-trusted-origins" aria-label="Permalink to &quot;Login redirect allowlist — set `TRUSTED_ORIGINS`&quot;">​</a></h3><p>Interactive login runs through the authorization-code flow against a per-realm <code>web</code> client whose redirect allowlist is built from the origin of <code>PUBLIC_URL</code> plus every entry in <code>TRUSTED_ORIGINS</code> (renamed from <code>ADDITIONAL_DOMAINS</code>).</p><p><strong>If your web UI is served from a different origin than <code>PUBLIC_URL</code></strong> (e.g. UI on <code>https://app.example.com</code>, server on <code>https://auth.example.com</code>) <strong>you must set</strong>:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TRUSTED_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">app.example.com</span></span></code></pre></div><p>Otherwise every login fails after the redirect with an opaque OAuth2 error. Entries may be bare hosts (expanded to both <code>http</code> and <code>https</code>) or full origins; comma-separated.</p><div class="warning custom-block"><p class="custom-block-title">Security</p><p>Each trusted origin is added to a <code>builtIn</code> (auto-consent) client carrying the <code>global</code> scope — an allowlisted origin can obtain full-permission user tokens. Only list origins you control.</p></div><h3 id="refresh-token-rotation-hard-cutover" tabindex="-1">Refresh-token rotation (hard cutover) <a class="header-anchor" href="#refresh-token-rotation-hard-cutover" aria-label="Permalink to &quot;Refresh-token rotation (hard cutover)&quot;">​</a></h3><p>Every <code>refresh_token</code> grant now rotates: the presented token is retired and a fresh pair is issued. Refresh tokens minted <strong>before</strong> the upgrade are rejected with <code>invalid_grant</code> — active users have to sign in once after the upgrade. Replaying an already-consumed refresh token revokes the whole session family (RFC 6819 §5.2.2.3). A multi-tab tolerance window can be configured via <code>TOKEN_REFRESH_GRACE_PERIOD</code> (seconds, default <code>0</code> = strict).</p><h3 id="access-token-ttl-default-lowered-3600-→-900-seconds" tabindex="-1">Access-token TTL default lowered: 3600 → 900 seconds <a class="header-anchor" href="#access-token-ttl-default-lowered-3600-→-900-seconds" aria-label="Permalink to &quot;Access-token TTL default lowered: 3600 → 900 seconds&quot;">​</a></h3><p>Shrinks the revocation blind spot for stateless JWKS-verifying adapters. Override via <code>TOKEN_ACCESS_MAX_AGE</code> (seconds) if your deployment depends on longer-lived access tokens.</p><h3 id="authorize-token-flows-are-realm-bound" tabindex="-1">Authorize &amp; token flows are realm-bound <a class="header-anchor" href="#authorize-token-flows-are-realm-bound" aria-label="Permalink to &quot;Authorize &amp; token flows are realm-bound&quot;">​</a></h3><p>An identity can only authorize (or redeem a code / refresh a token) against a client in <strong>its own realm</strong> — a cross-realm attempt yields <code>login_required</code> / <code>invalid_grant</code>. Consequences:</p><ul><li>Master-realm admins can no longer sign into other realms&#39; applications through the built-in <code>web</code> client; use an identity of the target realm.</li><li>A client identified <strong>by name</strong> at <code>/authorize</code> now requires a realm hint (<code>realm_id</code>), since every realm has a <code>web</code> client.</li></ul><h3 id="implicit-hybrid-response-types-removed" tabindex="-1">Implicit &amp; hybrid response types removed <a class="header-anchor" href="#implicit-hybrid-response-types-removed" aria-label="Permalink to &quot;Implicit &amp; hybrid response types removed&quot;">​</a></h3><p><code>response_type=code</code> is the only supported response type (OAuth 2.1 posture). Public clients must use PKCE and <code>state</code> unconditionally; the <code>id_token</code> is minted at the <code>/token</code> exchange. RPs still using <code>token</code> / <code>id_token</code> / hybrid response types must migrate to the code flow.</p><h3 id="rp-initiated-logout-discovery-corrections" tabindex="-1">RP-initiated logout &amp; discovery corrections <a class="header-anchor" href="#rp-initiated-logout-discovery-corrections" aria-label="Permalink to &quot;RP-initiated logout &amp; discovery corrections&quot;">​</a></h3><ul><li>New <code>end_session_endpoint</code>: <code>GET/POST /logout</code> (advertised in the realm discovery document). Downstream apps should end the shared authup session by redirecting there with an <code>id_token_hint</code>.</li><li><code>post_logout_redirect_uri</code> is honored only when it matches the client&#39;s <strong>new, separate</strong><code>post_logout_redirect_uri</code> column — a URI matching only the login <code>redirect_uri</code> is rejected. Set the column for clients that use post-logout redirects (the provisioned <code>web</code> client is populated automatically).</li><li>Discovery <code>revocation_endpoint</code> was corrected from <code>…/token</code> to <code>…/token/revoke</code> (RFC 7009).</li></ul><h3 id="minimum-password-length-raised-to-10" tabindex="-1">Minimum password length raised to 10 <a class="header-anchor" href="#minimum-password-length-raised-to-10" aria-label="Permalink to &quot;Minimum password length raised to 10&quot;">​</a></h3><p>New password writes (user create/update, registration, password reset) reject values shorter than 10 characters — configurable via <code>PASSWORD_MIN_LENGTH</code>. Existing password hashes keep verifying; nobody is forced to reset. File-provisioned users whose configured password is shorter than the floor now fail provisioning validation at startup.</p><h3 id="client-granttypes-is-now-enforced" tabindex="-1"><code>Client.grantTypes</code> is now enforced <a class="header-anchor" href="#client-granttypes-is-now-enforced" aria-label="Permalink to &quot;`Client.grantTypes` is now enforced&quot;">​</a></h3><p>A non-null <code>grantTypes</code> value (space- or comma-delimited) acts as an allowlist at the <code>/token</code> grants and the <code>/authorize</code> code request; violations fail with <code>unauthorized_client</code>. <code>null</code> keeps allow-all semantics, so only clients that <em>set</em> the column are affected — review clients that stored decorative values (e.g. a client listing only <code>authorization_code</code> will fail token refreshes until <code>refresh_token</code> is added). The provisioned per-realm <code>web</code> client already lists <code>authorization_code refresh_token</code>.</p><h3 id="also-notable-no-action-required" tabindex="-1">Also notable (no action required) <a class="header-anchor" href="#also-notable-no-action-required" aria-label="Permalink to &quot;Also notable (no action required)&quot;">​</a></h3><ul><li><strong>Session management</strong>: <code>GET/DELETE /sessions</code> API plus a sessions UI (&quot;This device&quot; marker, &quot;log out other devices&quot;, admin force-logout).</li><li><strong>OIDC prompt surface</strong>: <code>/authorize</code> supports <code>prompt</code> (<code>none|login|consent|select_account</code>), <code>max_age</code> and <code>login_hint</code>; the <code>@authup/client-web-kit</code> URL builder now defaults to <code>prompt=select_account</code>, so kit-based apps inherit an account chooser on lingering sessions (pass an explicit <code>prompt</code> to opt out).</li><li><strong>id_token claims</strong>: <code>auth_time</code> now reflects the real authentication instant and a <code>sid</code> (session id) claim is included.</li></ul>',80)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
